      (1, 1222, 4, '07EA8317', '4293807322', null, '2025-10-16', '2025-11-13 17:39:07', '2025-10-16', 472, 472, 'SIEMENS CONTACTOR', 1014, 275, 1, 'V', 'JES', null, null, 'JES', '2025-11-13 00:00:00', 'V', null, null, null, 12, 5, 0, false, null, 0, null, null, null, null, null, 0, true, null, null, null, 3, 2025, null, 10, 0, 0, 0, null, null, null, null, 'C', true, 10, 4, null, null, 0, 0, 0, 0, 0, 0, 0, 0, 0, null, null, null, null, 'N', 0, null, null),
